      "code": "import pytest
import impl
from hypothesis import given, strategies as st, settings

ints = st.integers(min_value=-5, max_value=15)
interval = st.tuples(ints, ints).map(lambda pair: (min(pair), max(pair)))
intervals_strategy = st.lists(interval, max_size=6)

@given(intervals=intervals_strategy)
@settings(max_examples=100)
def test_output_minute_coverage_matches_input_exactly(intervals):
    output = impl.merge_bookings(intervals)
    for minute in range(-6, 16):
        input_covered = any(s <= minute < e for s, e in intervals if s < e)
        output_count = sum(1 for s, e in output if s <= minute < e)
        if input_covered:
            assert output_count == 1, (
                f"minute {minute} covered by input {intervals} but appears in "
                f"{output_count} output blocks of {output}"
            )
        else:
            assert output_count == 0, (
                f"minute {minute} not covered by input {intervals} but appears in "
                f"output blocks of {output}"
            )
"
    }
  ]
}
